/** Fiche correspondant à un élément ({kind, name, exe, display}), ou null. */
function kbFind(kind, name, exe = '', display = '') {
  const short = `${kind}:${String(name || '').toLowerCase()}`;
  const key = `${short}|${String(exe || '').toLowerCase()}|${String(display || '').toLowerCase()}`;
  // « type:nom » seul pour les fiches ancrées (^svc:nom$), sinon nom, chemin et description
  for (const k of KB) if (k.m.test(short) || k.m.test(key)) return k;
  return null;
}

/** Réglages : uniquement des réglages documentés, réversibles, à l'effet réel.
   reg : valeurs écrites quand le réglage est appliqué (on) ou retiré (off ; null = valeur
   absente) ; def : valeur que Windows applique quand elle est absente.
   svc : réglage qui passe par un service (type de démarrage on / off).
   admin : droits requis. restart : effet après redémarrage ou nouvelle session.
   explorer : effet après redémarrage de l'Explorateur. */
const HKCU_ADV = 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Advanced';
const CDM = 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\ContentDeliveryManager';
const dw = (path, name, on, off, def) => ({ path, name, type: 'DWord', on, off, def });
const sz = (path, name, on, off, def) => ({ path, name, type: 'String', on, off, def });
const adv = (name, on, off, def) => dw(HKCU_ADV, name, on, off, def);

